begin;
do $$declare p uuid;req jsonb;res jsonb;again jsonb;reservation jsonb;q jsonb;begin
 select id into p from public.products where slug='spicy-lobster';
 req:=jsonb_build_object('requestId',gen_random_uuid(),'items',jsonb_build_array(jsonb_build_object('productId',p,'quantity',1)),'expectedSubtotalCentavos',169900,'recipient',jsonb_build_object('name','Test Customer','phone','09171234567'),'notes','','fulfillment','pickup','address',null,'destination',null,'quoteId',null);
 perform set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',true);
 res:=public.place_order(req);perform public.test_assert(res->>'code'='VERIFICATION_REQUIRED','unverified cannot order');
 perform set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
 res:=public.place_order(req);perform public.test_assert((res->>'ok')::boolean,'pickup order persisted');
 perform public.test_assert((res->'data'->>'deliveryFeeCentavos')::int=0,'pickup no delivery fee');
 perform public.test_assert(res->'data'->'recipient'->>'phone'='+639171234567','phone normalized server-side');
 again:=public.place_order(req);perform public.test_assert(again->'data'->>'id'=res->'data'->>'id','identical retry stable');
 again:=public.place_order(jsonb_set(req,'{notes}','"changed"'));perform public.test_assert(again->>'code'='REQUEST_CONFLICT','changed same ID denied');
 again:=public.place_order(jsonb_set(jsonb_set(req,'{requestId}',to_jsonb(gen_random_uuid())),'{expectedSubtotalCentavos}','1'));perform public.test_assert(again->>'code'='PRICE_CHANGED','stale total reviewed');
 again:=public.place_order(jsonb_set(jsonb_set(req,'{requestId}',to_jsonb(gen_random_uuid())),'{items,0,quantity}','100'));perform public.test_assert(again->>'code'='INVALID_CART','quantity100 denied');
 update public.products set active=false where id=p;
 again:=public.place_order(jsonb_set(req,'{requestId}',to_jsonb(gen_random_uuid())));perform public.test_assert(again->>'code'='ITEM_UNAVAILABLE','disabled menu denied');
 perform public.test_assert((public.get_my_order(jsonb_build_object('orderId',res->'data'->>'id'))->'data'->'items'->0->>'unitPriceCentavos')::int=169900,'history original price immutable');
 update public.products set active=true where id=p;
 reservation:=public.reserve_quote_request(jsonb_build_object('ownerId','10000000-0000-4000-8000-000000000001','destination',jsonb_build_object('lat',14.61,'lng',120.99)));
 q:=public.store_delivery_quote(jsonb_build_object('reservationId',reservation->'data'->>'id','distanceMetres',4000));
 req:=jsonb_set(req,'{requestId}',to_jsonb(gen_random_uuid()))||jsonb_build_object('fulfillment','delivery','address','Synthetic address for test only','destination',jsonb_build_object('lat',14.61,'lng',120.99),'quoteId',q->'data'->>'id');
 update restaurant_private.delivery_quotes set expires_at=clock_timestamp()-interval '1 second' where id=(q->'data'->>'id')::uuid;
 again:=public.place_order(req);perform public.test_assert(again->>'code'='QUOTE_EXPIRED','expired quote denied');
 update restaurant_private.delivery_quotes set expires_at=clock_timestamp()+interval '5 minutes' where id=(q->'data'->>'id')::uuid;
 perform set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
 again:=public.place_order(req);perform public.test_assert(again->>'code'='INVALID_QUOTE','foreign quote denied');
 again:=public.get_my_order(jsonb_build_object('orderId',res->'data'->>'id'));perform public.test_assert(again->>'code'='NOT_FOUND','other owner order hidden');
 perform set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
 update public.restaurant_settings set version=version+1 where id;
 again:=public.place_order(req);perform public.test_assert(again->>'code'='POLICY_CHANGED','stale policy denied');
end$$;
rollback;
